  "boundaries": [
    "Nothing has been approved: no landlord consent, no contractor assigned, no spend.",
    "Tenant replacement is not agreed, and ownership and removal at move-out are not agreed.",
    "The fault itself is not diagnosed; the tenant's claim it cannot be fixed is unverified.",
    "No visit is booked."
  ],
  "remaining_work": [
    "Landlord contact and decision (owner: maintenance team via ESC-102).",
    "Tenant's photo, error code and model number (owner: tenant).",
    "Once decided: assign a contractor or send written consent terms, then update the tenant (owner: operations).",
    "Review on 2025-07-29."
  ],
  "missing_info": [
    "Landlord contact details on the property record",
    "Landlord decision on repair or tenant replacement",
    "Diagnosis or photo of the fault and machine make/model"
  ],
  "outcome": "action_taken",
  "severity": "routine",
  "summary": "The tenant asked to replace the existing washing machine with their own, which needs landlord consent and agreed terms on ownership. The tenant was told in writing to wait for the landlord's decision and asked for a photo, error code and model number. The job is escalated for the missing landlord contact and held for review on 2025-07-29.",
  "answers": [
    {
      "question": "Where does the case stand right now, and what is outstanding?",
      "answer": "Intake stage, routine. Nothing has been decided. Outstanding: landlord decision (repair versus tenant replacement with ownership and removal terms), landlord contact, tenant's photo and model/error code, and diagnosis."
    },
    {
      "question": "What is the next action, who is it for, and through which channel?",
      "answer": "Reply to the tenant by email on the existing thread (A1). Escalate to maintenance for landlord contact and decision (A2). Hold for landlord with review on 2025-07-29 (A3)."
    },
    {
      "question": "Does anything need a human decision, and why?",
      "answer": "Yes. Landlord consent for a tenant-owned replacement of an appliance that was there at move-in is an alteration decision the agency cannot make, and the landlord cannot be contacted because no contact is on the property record. Escalated at P3 (not urgent; no safety risk)."
    }
  ],
  "actions_claimed": [
    {
      "ledger_id": "A1",
      "description": "Email to tenant: landlord decision pending, do not buy or install yet, requested photo, error code and model number"
    },
    {
      "ledger_id": "A2",
      "description": "Escalated ESC-102 (P3, maintenance) for landlord contact and decision"
    },
    {
      "ledger_id": "A3",
      "description": "Ticket on hold, waiting for landlord, review 2025-07-29"
    }
  ],
  "failed_actions": [],
  "conflicts": [
    "The tenant says the machine cannot be fixed, but no diagnosis has been done. Treated as unverified."
  ],
  "assumptions": [
    "The washing machine belongs to the landlord, since it was present at move-in and the tenant says it was there when they moved in.",
    "Today is Saturday 2025-07-26, so the review date is the next working day after the weekend-adjusted window."
  ]
}

